    min_distance_m = float(config["limits"].get("min_distance_m", 0.25))
    peer_timeout_s = float(config.get("peer_timeout_s", 0.7))
    targets = target_poses()
    pair_targets = target_pair_distances()

    series = {}
    times = {}
    for robot_id in ROBOT_IDS:
        samples = sorted(stamps["states"][robot_id])
        series[robot_id] = samples
        times[robot_id] = [sample[0] for sample in samples]

    def pose_at(robot_id, when):
        samples = series[robot_id]
        if not samples:
            return None
        index = bisect.bisect_right(times[robot_id], when) - 1
        if index < 0:
            return None
        return samples[index]

    grid = []
    tick = start + mission_at
    while tick <= end:
        grid.append(tick)
        tick += 0.05

    errors = []
    spacings = []
    pair_errors = []
    for when in grid:
        poses = {robot_id: pose_at(robot_id, when) for robot_id in ROBOT_IDS}
        if any(value is None for value in poses.values()):
            continue
        errors.append(
            (
                when,
                max(
                    math.hypot(
                        poses[robot_id][1] - targets[robot_id][0],
                        poses[robot_id][2] - targets[robot_id][1],
                    )
                    for robot_id in ROBOT_IDS
                ),
            )
        )
        spacings.append(
            (
                when,
                min(math.hypot(poses[a][1] - poses[b][1], poses[a][2] - poses[b][2]) for a, b in PAIRS),
            )
        )
        pair_errors.append(
            (
                when,
                max(
                    abs(
                        math.hypot(poses[a][1] - poses[b][1], poses[a][2] - poses[b][2])
                        - pair_targets[(a, b)]
                    )
                    for a, b in PAIRS
                ),
            )
        )

    def hold_from(entries, limit, hold_s=1.0):
        for index, entry in enumerate(entries):
            if entry[0] + hold_s > end:
                return None
            window = [item for item in entries[index:] if item[0] <= entry[0] + hold_s]
            if window and all(item[1] <= limit for item in window):
                return entry[0] - (start + mission_at)
        return None

    settled_s = hold_from(errors, TOLERANCE_M)
    tail = [item for item in errors if item[0] >= end - 1.0]
    final_max_error = max((item[1] for item in tail), default=float("nan"))
    max_pair_error = max((item[1] for item in pair_errors if item[0] >= end - 1.0), default=float("nan"))
    minimum_spacing = min((item[1] for item in spacings), default=float("nan"))

    def stopped_after(robot_id, moment):
        samples = [sample for sample in stamps["cmds"][robot_id] if sample[0] >= moment]
        for index, sample in enumerate(samples):
            if math.hypot(sample[1], sample[2]) <= 1e-9 and not sample[4]:
                if all(math.hypot(later[1], later[2]) <= 1e-6 for later in samples[index:]):
                    return sample[0]
        return None
