        if candidates:
            pre_fault_error = candidates[-1]

    reasons = []
    if settled_s is None:
        reasons.append("formation did not settle within tolerance")
    if math.isfinite(pre_fault_error) and pre_fault_error > TOLERANCE_M:
        reasons.append(f"slot error before fault {pre_fault_error:.3f} m > {TOLERANCE_M} m")
    if math.isfinite(minimum_spacing) and minimum_spacing < min_distance_m:
        reasons.append(f"minimum spacing {minimum_spacing:.3f} m < {min_distance_m} m")
    for fault in faults:
        if fault["max_stop_latency_s"] is None:
            reasons.append(f"{fault['kind']} on {fault['robot']}: not every car stopped")
        elif fault["max_stop_latency_s"] > fault["deadline_s"]:
            reasons.append(
                f"{fault['kind']} on {fault['robot']}: stop latency {fault['max_stop_latency_s']} s"
                f" > {fault['deadline_s']} s"
            )
        if fault["nonzero_commands_after_stop"]:
            reasons.append(
                f"{fault['kind']} on {fault['robot']}: {fault['nonzero_commands_after_stop']}"
                " nonzero commands after stop"
            )

    return {
        "scenario": scenario["name"],
        "mode": scenario["mode"],
        "config": scenario["config"],
        "link": {
            "delay_ms": scenario.get("delay_ms", 0.0),
            "jitter_ms": scenario.get("jitter_ms", 0.0),
            "loss": scenario.get("loss", 0.0),
        },
        "actuator_tau_s": scenario.get("actuator_tau", 0.0),
        "pose_noise_m": scenario.get("pose_noise", 0.0),
        "min_distance_m": min_distance_m,
        "settled_s": None if settled_s is None else round(settled_s, 3),
        "final_max_slot_error_m": round(final_max_error, 4),
        "max_pair_spacing_error_m": round(max_pair_error, 4),
        "minimum_spacing_m": round(minimum_spacing, 4),
        "faults": faults,
        "verdict": "PASS" if not reasons else "FAIL",
        "reasons": reasons,
    }
