$repo = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$manifestPath = (Resolve-Path $Manifest).Path
$fleet = Get-Content $manifestPath -Raw | ConvertFrom-Json

$bundleLocal = (Resolve-Path (Join-Path $repo $fleet.bundle)).Path
$sha = (Get-FileHash $bundleLocal -Algorithm SHA256).Hash.ToLower()
$size = (Get-Item $bundleLocal).Length
Write-Output "bundle : $bundleLocal"
Write-Output "sha256 : $sha"
Write-Output "size   : $size bytes"
Write-Output ""

$env:SSH_ASKPASS = (Join-Path $PSScriptRoot "askpass.cmd")
$env:SSH_ASKPASS_REQUIRE = "force"
$env:DISPLAY = "dummy"
$env:MENTORPI_PASSWORD = $fleet.password

$results = @()
$jobs = @()
foreach ($car in $fleet.cars) {
  if ($Only.Count -gt 0 -and $Only -notcontains $car.robot_id -and $Only -notcontains $car.ip) { continue }
  $script:one = {
    param($car, $user, $password, $sha, $bundleLocal, $remoteBundle, $skipUpload, $root, $fleetDomain)
    $env:SSH_ASKPASS = Join-Path $root "askpass.cmd"
    $env:SSH_ASKPASS_REQUIRE = "force"
    $env:DISPLAY = "dummy"
    $env:MENTORPI_PASSWORD = $password
    $target = "$user@$($car.ip)"
    $log = [System.Collections.Generic.List[string]]::new()
    $ok = $true
    # Gate on TCP 22 rather than ICMP: the lab Wi-Fi drops a large share of
    # ping replies while SSH works fine, so a ping gate reports healthy cars as
    # unreachable and the flash never starts.
    function Test-SshPort([string]$ComputerName) {
      for ($i = 1; $i -le 5; $i++) {
        $client = New-Object Net.Sockets.TcpClient
        try {
          if ($client.ConnectAsync($ComputerName, 22).Wait(4000) -and $client.Connected) { return $true }
        } catch { }
        finally { $client.Close() }
        Start-Sleep -Seconds 3
      }
      return $false
    }
    if (-not (Test-SshPort $car.ip)) {
      return [pscustomobject]@{ ip = $car.ip; robot_id = $car.robot_id; ok = $false; note = "ssh port 22 unreachable" ; log = $log.ToArray() }
    }
    if (-not $skipUpload) {
      $log.Add("[upload] $bundleLocal -> $remoteBundle")
      $uploaded = $false
      for ($attempt = 1; $attempt -le 4 -and -not $uploaded; $attempt++) {
        & scp -o StrictHostKeyChecking=accept-new -o LogLevel=ERROR -q $bundleLocal "${target}:$remoteBundle" 2>&1 | ForEach-Object { $log.Add($_) }
        if ($LASTEXITCODE -eq 0) { $uploaded = $true } else { $log.Add("[upload] attempt $attempt failed"); Start-Sleep -Seconds 3 }
      }
      if (-not $uploaded) { return [pscustomobject]@{ ip = $car.ip; robot_id = $car.robot_id; ok = $false; note = "scp failed"; log = $log.ToArray() } }
    }
    $remote = "$root\remote_install.sh"
    $text = ((Get-Content -Raw $remote) -replace "`r", "")
    $tmp = Join-Path $root ("payload-" + [Guid]::NewGuid().ToString("N").Substring(0,8) + ".sh")
    [IO.File]::WriteAllText($tmp, $text, (New-Object Text.UTF8Encoding($false)))
    $remoteScript = "/tmp/cz225-install-" + [Guid]::NewGuid().ToString("N").Substring(0,8) + ".sh"
    $code = 1
    for ($attempt = 1; $attempt -le 3 -and $code -ne 0; $attempt++) {
      $scriptUploaded = $false
      for ($inner = 1; $inner -le 4 -and -not $scriptUploaded; $inner++) {
        & scp -o StrictHostKeyChecking=accept-new -o LogLevel=ERROR -q $tmp "${target}:$remoteScript" 2>&1 | ForEach-Object { $log.Add($_) }
        if ($LASTEXITCODE -eq 0) { $scriptUploaded = $true } else { Start-Sleep -Seconds 3 }
      }
      if (-not $scriptUploaded) { $log.Add("[install] could not stage the remote script"); continue }
      $out = & ssh -T -o ConnectTimeout=20 -o NumberOfPasswordPrompts=1 -o StrictHostKeyChecking=accept-new -o LogLevel=ERROR -o ServerAliveInterval=15 -o ServerAliveCountMax=6 $target "bash $remoteScript $($car.robot_id) $sha $remoteBundle $fleetDomain; rc=`$?; rm -f $remoteScript; exit `$rc" 2>&1
      $out | ForEach-Object { $log.Add($_) }
      $code = $LASTEXITCODE
      if ($code -ne 0) { $log.Add("[install] attempt $attempt exited $code; retrying"); Start-Sleep -Seconds 5 }
    }
    Remove-Item $tmp -Force -ErrorAction SilentlyContinue
    [pscustomobject]@{ ip = $car.ip; robot_id = $car.robot_id; ok = ($code -eq 0); note = "exit=$code"; log = $log.ToArray() }
  }
  if ($Parallel -gt 1) { $jobs += Start-Job -ScriptBlock $script:one -ArgumentList $car, $fleet.user, $fleet.password, $sha, $bundleLocal, $fleet.remote_bundle, [bool]$SkipUpload, $PSScriptRoot, $fleet.fleet_domain }
  else { $results += & $script:one $car $fleet.user $fleet.password $sha $bundleLocal $fleet.remote_bundle ([bool]$SkipUpload) $PSScriptRoot $fleet.fleet_domain }
}
foreach ($j in $jobs) { $j | Wait-Job | Out-Null; $results += Receive-Job $j; $j | Remove-Job -Force }

$reportDir = Join-Path $PSScriptRoot "reports"
New-Item -ItemType Directory -Force -Path $reportDir | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
foreach ($r in $results) {
  $file = Join-Path $reportDir "$stamp-$($r.robot_id)-$($r.ip).log"
  $r.log | Set-Content -Path $file -Encoding UTF8
  Write-Output ""
  Write-Output "===== $($r.robot_id)  $($r.ip)  ok=$($r.ok)  $($r.note)"
  Write-Output "log: $file"
  $r.log | Where-Object { $_ -match "^###|FATAL|Error|error:" } | ForEach-Object { "   $_" }
}
Write-Output ""
Write-Output "summary:"
$results | Select-Object robot_id, ip, ok, note | Format-Table -AutoSize
if ($results | Where-Object { -not $_.ok }) { exit 1 }

