        for attempt in range(1, attempts + 1):
            try:
                if not self.connect():
                    raise ConnectionError(self.ip)
                with self.sftp.open(remote, "w") as handle:
                    handle.write(text)
                self.sftp.chmod(remote, mode)
                return True
            except Exception as exc:
                self.shutdown()
                self.emit("script upload attempt %d/%d failed: %s" % (attempt, attempts, exc))
                if attempt < attempts:
                    time.sleep(2 * attempt)
        return False

    def get(self, remote, local, attempts=3):
        folder = os.path.dirname(os.path.abspath(local))
        if folder:
            os.makedirs(folder, exist_ok=True)
        for attempt in range(1, attempts + 1):
            try:
                if not self.connect():
                    raise ConnectionError(self.ip)
                self.sftp.get(remote, local)
                return True
            except Exception as exc:
                self.shutdown()
                self.emit("download attempt %d/%d failed: %s" % (attempt, attempts, exc))
                if attempt < attempts:
                    time.sleep(2 * attempt)
        return False


def shlex_quote(text):
    return "'" + str(text).replace("'", "'\"'\"'") + "'"


def load_fleet(path=None):
    with open(path or MANIFEST, "r", encoding="utf-8") as handle:
        return json.load(handle)


def select_cars(fleet, only=None):
    """Build the Car objects; `only` accepts robot ids or ip addresses."""
    wanted = None
    if only:
        wanted = set()
        for item in only:
            wanted.update(part.strip() for part in str(item).split(",") if part.strip())
    cars = []
    for entry in fleet["cars"]:
        if wanted and entry["robot_id"] not in wanted and entry["ip"] not in wanted:
            continue
        cars.append(Car(entry["ip"], entry["robot_id"], fleet["user"], fleet["password"]))
    return cars


def map_cars(cars, worker, jobs=1):
    """Run `worker(car)` for every car, optionally with several in flight."""
    results = {}
    if jobs > 1 and len(cars) > 1:
        from concurrent.futures import ThreadPoolExecutor

        with ThreadPoolExecutor(max_workers=jobs) as pool:
            futures = {pool.submit(worker, car): car for car in cars}
            for future, car in futures.items():
                results[car.robot_id] = future.result()
    else:
        for car in cars:
            results[car.robot_id] = worker(car)
    return results
