"""全网段扫描：ping sweep + ARP 表 + SSH 端口探测，按 MAC 前缀认车。"""
import concurrent.futures, socket, subprocess, sys

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

MAC_PREFIX = "88-a2-9e-9f"
KNOWN = {"88-a2-9e-9f-9b-ea": "robot1", "88-a2-9e-9f-a0-37": "robot2",
         "88-a2-9e-9f-9e-12": "robot3", "88-a2-9e-9f-a0-01": "robot4"}


def ping(ip):
    out = subprocess.run(["ping", "-n", "1", "-w", "250", ip],
                         capture_output=True, text=True, errors="replace").stdout
    return ip, ("TTL=" in out)


def ssh_open(ip, timeout=1.5):
    sock = socket.socket(); sock.settimeout(timeout)
    try:
        sock.connect((ip, 22)); return True
    except Exception:
        return False
    finally:
        sock.close()


def arp_table():
    out = subprocess.run(["arp", "-a"], capture_output=True, text=True,
                         errors="replace").stdout
    rows = []
    for line in out.splitlines():
        parts = line.split()
        if len(parts) >= 2 and parts[0].startswith("192.168.1."):
            rows.append((parts[0], parts[1].lower().replace(":", "-")))
    return rows


targets = ["192.168.1.%d" % index for index in range(1, 255)]
alive = []
with concurrent.futures.ThreadPoolExecutor(max_workers=96) as pool:
    for ip, ok in pool.map(ping, targets):
        if ok:
            alive.append(ip)

def sort_key(ip):
    return int(ip.rsplit(".", 1)[1])

alive.sort(key=sort_key)
print("== alive (%d) ==" % len(alive), flush=True)
for ip in alive:
    print("   %s  ssh=%s" % (ip, "OK" if ssh_open(ip) else "no"), flush=True)

print("", flush=True)
print("== arp table ==", flush=True)
for ip, mac in arp_table():
    tag = KNOWN.get(mac, "")
    if mac.startswith(MAC_PREFIX):
        tag = KNOWN.get(mac, "CAR?") + "  <== 小车"
    print("   %-15s %-18s %s" % (ip, mac, tag), flush=True)

print("", flush=True)
found = [ip for ip, mac in arp_table() if mac.startswith(MAC_PREFIX)]
print("== 小车地址 ==", flush=True)
print("   %s" % (", ".join("%s (%s)" % (ip, KNOWN.get(mac, "?")) 
