#!/usr/bin/env python3
"""Persistent SSH/SFTP sessions for the CZ225 MentorPi fleet.

Win32 OpenSSH cannot multiplex connections (ControlMaster needs unix sockets),
so the earlier PowerShell helpers paid a fresh TCP handshake *and* a fresh
password authentication for every single ssh/scp call.  On the lab Wi-Fi that is
slow and it is the main reason one-shot commands came back flaky.  This module
keeps one authenticated connection per car alive for the whole run and
multiplexes every command and upload over it.
"""

from __future__ import annotations

import json
import os
import time

import paramiko

HERE = os.path.dirname(os.path.abspath(__file__))
MANIFEST = os.path.join(HERE, "fleet.json")
REPO = os.path.dirname(os.path.dirname(HERE))


class Car:
    """One car, backed by one long-lived SSH connection."""

    def __init__(self, ip, robot_id, user, password):
        self.ip = ip
        self.robot_id = robot_id
        self.user = user
        self.password = password
        self.client = None
        self.sftp = None
        self.lines = []

    # ------------------------------------------------------------ output
    def emit(self, text):
        """Print a line prefixed with the car name and keep it for the report."""
        text = str(text).replace("\r\n", "\n").rstrip("\n")
        if not text:
            return
        for line in text.split("\n"):
            self.lines.append(line)
            print("%-7s | %s" % (self.robot_id, line), flush=True)

    def transcript(self):
        return "\n".join(self.lines)

    # -------------------------------------------------------- connection
    def alive(self):
        if self.client is None:
            return False
        transport = self.client.get_transport()
        return bool(transport and transport.is_active())

    def shutdown(self):
        for resource in (self.sftp, self.client):
            try:
                if resource is not None:
                    resource.close()
            except Exception:
                pass
        self.sftp = None
        self.client = None

    def connect(self, attempts=4):
        """Return True once a working connection exists, reconnecting if needed."""
        if self.alive():
            return True
        self.shutdown()
        for attempt in range(1, attempts + 1):
            started = time.time()
            try:
                client = paramiko.SSHClient()
                client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                client.connect(
                    self.ip,
                    port=22,
                    username=self.user,
                    password=self.password,
                    timeout=8,
                    banner_timeout=25,
                    auth_timeout=25,
                    look_for_keys=False,
                    allow_agent=False,
                )
                transport = client.get_transport()
                # Keeps NAT/idle timers from silently killing a session we
                # intend to hold for the whole run.
                transport.set_keepalive(10)
                self.client = client
                self.sftp = paramiko.SFTPClient.from_transport(transport)
                self.sftp.sock.settimeout(30)
                self.emit("connected in %.1fs (attempt %d)" % (time.time() - started, attempt))
                return True
            except Exception as exc:
                self.shutdown()
                self.emit("connect attempt %d/%d failed: %s" % (attempt, attempts, exc))
                if attempt < attempts:
                    time.sleep(min(2 * attempt, 6))
        return False

    # ------------------------------------------------------------ running
    def run(self, command, timeout=900):
        """Run a shell command, streaming its output.  Returns (exit_code, output)."""
        if not self.connect():
            return 255, "unreachable"
        channel = self.client.get_transport().open_session(timeout=20)
        channel.set_combine_stderr(True)
        channel.settimeout(20.0)
        channel.exec_command(command)
        collected = []
        pending = ""
        deadline = time.time() + timeout
        while True:
            if channel.recv_ready():
                data = channel.recv(65536)
                if data:
                    pending += data.decode("utf-8", "replace")
                    while "\n" in pending:
                        line, pending = pending.split("\n", 1)
                        collected.append(line)
                        self.emit(line)
                    continue
            if channel.exit_status_ready():
                break
            if time.time() > deadline:
                channel.close()
                self.emit("TIMEOUT after %ds" % timeout)
                return 124, "\n".join(collected)
            time.sleep(0.05)
        while channel.recv_ready():
            data = channel.recv(65536)
            if data:
                pending += data.decode("utf-8", "replace")
        if pending.strip():
            collected.append(pending.rstrip("\n"))
            self.emit(pending.rstrip("\n"))
        code = channel.recv_exit_status()
        channel.close()
        return code, "\n".join(collected)

    def sudo(self, command, timeout=900):
        return self.run("sudo -n bash -lc %s" % shlex_quote(command), timeout=timeout)

    # ---------------------------------------------------------- file i/o
    def put(self, local, remote, attempts=4):
        for attempt in range(1, attempts + 1):
            try:
                if not self.connect():
                    raise ConnectionError(self.ip)
                self.sftp.put(local, remote)
                return True
            except Exception as exc:
                self.shutdown()
                self.emit("upload attempt %d/%d failed: %s" % (attempt, attempts, exc))
                if attempt < attempts:
                    time.sleep(2 * attempt)
        return False

    def put_text(self, text, remote, mode=0o755, attempts=3):
        for attempt in range(1, attempts + 1):
            try:
                if not self.connect():
                    raise ConnectionError(self.ip)
                with self.sftp.open(remote, "w") as handle:
                    handle.write(text)
                self.sftp.chmod(remote, mode)
                return True
            except Exception as exc:
                self.shutdown()
                self.emit("script upload attempt %d/%d failed: %s" % (attempt, attempts, exc))
                if attempt < attempts:
                    time.sleep(2 * attempt)
        return False

    def get(self, remote, local, attempts=3):
        folder = os.path.dirname(os.path.abspath(local))
        if folder:
            os.makedirs(folder, exist_ok=True)
        for attempt in range(1, attempts + 1):
            try:
                if not self.connect():
                    raise ConnectionError(self.ip)
                self.sftp.get(remote, local)
                return True
            except Exception as exc:
                self.shutdown()
                self.emit("download attempt %d/%d failed: %s" % (attempt, attempts, exc))
                if attempt < attempts:
                    time.sleep(2 * attempt)
        return False


def shlex_quote(text):
    return "'" + str(text).replace("'", "'\"'\"'") + "'"


def load_fleet(path=None):
    with open(path or MANIFEST, "r", encoding="utf-8") as handle:
        return json.load(handle)


def select_cars(fleet, only=None):
    """Build the Car objects; `only` accepts robot ids or ip addresses."""
    wanted = None
    if only:
        wanted = set()
        for item in only:
            wanted.update(part.strip() for part in str(item).split(",") if part.strip())
    cars = []
    for entry in fleet["cars"]:
        if wanted and entry["robot_id"] not in wanted and entry["ip"] not in wanted:
            continue
        cars.append(Car(entry["ip"], entry["robot_id"], fleet["user"], fleet["password"]))
    return cars


def map_cars(cars, worker, jobs=1):
    """Run `worker(car)` for every car, optionally with several in flight."""
    results = {}
    if jobs > 1 and len(cars) > 1:
        from concurrent.futures import ThreadPoolExecutor

        with ThreadPoolExecutor(max_workers=jobs) as pool:
            futures = {pool.submit(worker, car): car for car in cars}
            for future, car in futures.items():
                results[car.robot_id] = future.result()
    else:
        for car in cars:
            results[car.robot_id] = worker(car)
    return results

